<div class="seom-panel"><h2>WooCommerce SEO</h2><?php if (!class_exists('WooCommerce')): ?><div class="notice notice-warning inline"><p>WooCommerce is not active. Product SEO controls will appear automatically when WooCommerce becomes active.</p></div><?php else: ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="seom_save_woocommerce"><?php wp_nonce_field('seom_save_woocommerce'); ?><div class="seom-toggle-list"><label class="seom-toggle-row"><span><strong>Product Schema</strong><small>Output Product, Offer, price, currency and availability structured data for products.</small></span><input type="checkbox" name="wc_schema" value="1" <?php checked((int)seom_get('wc_schema',1),1); ?>></label><label class="seom-toggle-row"><span><strong>Product Open Graph</strong><small>Output product price and currency Open Graph properties.</small></span><input type="checkbox" name="wc_og" value="1" <?php checked((int)seom_get('wc_og',1),1); ?>></label><label class="seom-toggle-row"><span><strong>Noindex hidden products</strong><small>Keep catalog-hidden products out of search results.</small></span><input type="checkbox" name="wc_noindex_hidden" value="1" <?php checked((int)seom_get('wc_noindex_hidden',1),1); ?>></label></div><p><button class="button button-primary">Save WooCommerce SEO</button></p></form><?php endif; ?></div>
